{
  "candidate_edge_types": [
    {
      "name": "INVESTIGATES_FAILURE_CAUSE",
      "definition": "A diagnostic action (such as searching or inspecting the codebase) performed in response to an observed execution failure in order to locate the source of that failure.",
      "source_description": "An observed execution failure or error produced by a prior command.",
      "target_description": "A diagnostic action that searches or inspects the codebase to locate the cause of the observed failure."
    },
    {
      "name": "REPAIRS_LOCATED_DEFECT",
      "definition": "A modification applied to source code to resolve a defect whose location was previously identified by a diagnostic action.",
      "source_description": "A located defective code site or root cause of an observed failure.",
      "target_description": "A source-modifying action that changes the code to remove the located defect."
    },
    {
      "name": "RERUNS_FAILED_CHECK_AFTER_REPAIR",
      "definition": "Re-execution of a verification step that previously failed, performed after a repair action, in order to confirm that the failure has been resolved.",
      "source_description": "A repair action applied to resolve a previously observed failure.",
      "target_description": "A re-execution of the verification step that previously produced the failure."
    },
    {
      "name": "VERIFIES_INSTALLED_ARTIFACT_IN_TARGET_ENVIRONMENT",
      "definition": "An execution that loads or exercises the installed artifact from outside its source tree to confirm the installation is functional in its intended environment.",
      "source_description": "A completed installation or build of an artifact.",
      "target_description": "An execution of the installed artifact from its target environment, outside the source directory."
    },
    {
      "name": "RUNS_BROADER_TEST_SUITE_AFTER_VERIFICATION",
      "definition": "An action that runs a broader automated test suite following a successful targeted verification, in order to check overall functionality.",
      "source_description": "A successful targeted verification of the primary use case.",
      "target_description": "A broader test-suite execution covering additional functionality."
    },
    {
      "name": "INITIATES_TASK_COMPLETION_AFTER_SUCCESSFUL_VERIFICATION",
      "definition": "A task-completion action performed only after verification and test results have confirmed that the task requirements are satisfied.",
      "source_description": "Successful verification or test results confirming the task requirements.",
      "target_description": "A task completion action that finalizes the execution."
    }
  ]
}

